/** Public bytes generated by actual quote/planner/signer/finalized-reader fixtures;
 * declarations below are consistency checks, never independent chain authority. */
import {describe,it,expect,vi} from 'vitest';
import {MiningTaxClaimRecoveryEnvelopeSchema as Schema,MiningTaxClaimSubmitRequestSchema,validateMiningTaxClaimRecoveryEnvelope} from './miningTaxClaimRecoveryApi';
import fixtures from './testFixtures/miningTaxClaimRecoveryApi.json';
const fixture=(kind:keyof typeof fixtures='combined')=>structuredClone(fixtures[kind]);
describe('original KEEP tax recovery public contract',()=>{
 it.each(['claim','combined','split','setup'] as const)('preserves actual finalized-reader %s receipt, immutable consent and original microseconds',kind=>{
  const f=fixture(kind);expect(Schema.parse(f)).toEqual(f);expect(f.settlement.settledAt).toContain('.123456Z');expect(f.settlement.receipt.journalClearingAuthorized).toBe(false);
 });
 it('recovers actual finalized fee above the original measurement but within saved user caps',()=>{
  const f=fixture('aboveQuote');expect(f.preparation.transactions[0]!.feeLamports).toBe('5');expect(f.settlement.receipt.feeLamports).toBe('6');expect(f.preparation.caps.maxFeeLamports).toBe('10');
  expect(Schema.parse(f)).toEqual(f);expect(f.settlement.receipt.finalityAuthenticated).toBe(true);expect(f.settlement.receipt.journalClearingAuthorized).toBe(false);
 });
 it('infers unknown, prepared and signed only from the retained evidence',()=>{
  const f=fixture(),prepared={...f,status:'prepared',wires:[],settlement:null};expect(Schema.safeParse(prepared).success).toBe(true);
  expect(Schema.safeParse({...prepared,status:'unknown',claimId:null,preparation:null}).success).toBe(true);
  expect(Schema.safeParse({...f,status:'signed',settlement:null}).success).toBe(true);
  for(const status of ['unknown','prepared','signed','setup'])expect(Schema.safeParse({...f,status}).success).toBe(false);
  expect(Schema.safeParse({...prepared,status:'unknown'}).success).toBe(false);
 });
 it('allows sparse original signed custody, but settlement requires its complete ordered prefix',()=>{
  const f=fixture('split');expect(Schema.safeParse({...f,status:'signed',settlement:null,wires:[f.wires[1]]}).success).toBe(true);
  for(const wires of [[f.wires[1]],[f.wires[1],f.wires[0]],[f.wires[0],f.wires[0]]])expect(Schema.safeParse({...f,wires}).success).toBe(false);
  const setup=fixture('setup');expect(Schema.safeParse(setup).success).toBe(true);expect(Schema.safeParse({...setup,wires:[setup.wires[0]]}).success).toBe(true);
  expect(Schema.safeParse({...setup,settlement:{...setup.settlement,claimFinalized:true}}).success).toBe(false);
 });
 it('binds owner/key/claim through preparation, wires and settlement',()=>{
  for(const field of ['wallet','idempotencyKey','claimId'] as const){const f=fixture(),changed=field==='wallet'?f.preparation.identity.programId:'ffffffff-ffff-4fff-8fff-ffffffffffff';
   for(const location of ['envelope','preparation','wire','settlement']){const x=structuredClone(f);const target=location==='envelope'?x:location==='wire'?x.wires[0]!:location==='preparation'?x.preparation:x.settlement;target[field]=changed;expect(Schema.safeParse(x).success,`${location}.${field}`).toBe(false);}
  }
 });
 it('binds declared original hashes/signatures, exact message suffix and ordinal/kind',()=>{
  for(const change of ['ordinal','kind','message','wireHash','receiptHash','signature','signatureBytes','messageBytes','length']){const f=fixture(),w=f.wires[0]!,r=f.settlement.receipt.transactions[0]!;
   if(change==='ordinal')w.ordinal=1;if(change==='kind')w.kind='claim';if(change==='message')w.messageSha256='ab'.repeat(32);if(change==='wireHash')w.wireSha256='ab'.repeat(32);if(change==='receiptHash')r.messageSha256='ab'.repeat(32);if(change==='signature')r.signature=f.preparation.identity.programId;
   if(change==='signatureBytes')w.signedTransactionHex='01'+'ab'.repeat(64)+w.signedTransactionHex.slice(130);if(change==='messageBytes')w.signedTransactionHex=w.signedTransactionHex.slice(0,-2)+'00';if(change==='length')w.signedTransactionHex+='00';
   expect(Schema.safeParse(f).success,change).toBe(false);
  }
 });
 it('retains syntax-only limits: matching hash strings do not authenticate cryptography',()=>{
  const f=fixture(),hash='ab'.repeat(32);f.preparation.transactions[0]!.messageSha256=hash;f.wires[0]!.messageSha256=hash;f.settlement.receipt.transactions[0]!.messageSha256=hash;expect(Schema.safeParse(f).success).toBe(true);
 });
 it('binds original term, claimant spot and reviewed source instead of current winners',()=>{
  for(const field of ['round','spot','term','pool','cursor','wallet']){const f=fixture(),r=f.settlement.receipt as unknown as Record<string,unknown>;r[field]=field==='spot'?1:field==='round'?'999':f.preparation.identity.keepMint;expect(Schema.safeParse(f).success,field).toBe(false);}
  for(const field of ['genesisHash','programId','reviewedDeploymentSlot','reviewedProgramDataSha256']){const f=fixture(),s=f.settlement.receipt.source as unknown as Record<string,unknown>;s[field]=field==='reviewedDeploymentSlot'?1:field==='reviewedProgramDataSha256'?'ab'.repeat(32):f.preparation.identity.keepMint;expect(Schema.safeParse(f).success,field).toBe(false);}
 });
 it('requires exact intended payment and cumulative claim, with observed counters at least historical execution',()=>{
  for(const change of ['paid','cumulative','pool','global','current','setup-paid']){const f=fixture(change==='setup-paid'?'setup':'combined'),r=f.settlement.receipt,t=r.transactions[0]!;
   if(change==='paid')r.paidKeepBaseUnits='2';if(change==='cumulative')t.claimedCumulativeBaseUnits='4';if(change==='pool')t.poolPaidAfterClaimBaseUnits='0';if(change==='global')t.globalTaxPaidAfterClaimBaseUnits='0';if(change==='current')t.currentClaimedTotal='0';if(change==='setup-paid'){r.paidKeepBaseUnits='1';t.paidKeepBaseUnits='1';}
   expect(Schema.safeParse(f).success,change).toBe(false);
  }
 });
 it('checks exact aggregate costs against saved user caps, allowing lower rent after prefunding',()=>{
  const f=fixture(),t=f.settlement.receipt.transactions[0]!;t.rentLamports='0';f.settlement.receipt.rentLamports='0';expect(Schema.safeParse(f).success).toBe(true);
  for(const field of ['feeLamports','rentLamports'] as const){const x=fixture(),overCap=(BigInt(x.preparation.caps[field==='feeLamports'?'maxFeeLamports':'maxRentLamports'])+1n).toString();x.settlement.receipt.transactions[0]![field]=overCap;x.settlement.receipt[field]=overCap;expect(Schema.safeParse(x).success).toBe(false);}
  const x=fixture();x.settlement.receipt.feeLamports='0';expect(Schema.safeParse(x).success).toBe(false);
 });
 it('rejects stale receipt slots, clocks, finality/source labels and forged authority flags',()=>{
  for(const change of ['slot','clock','bank','term-context','source','finality','clear','sign','broadcast','wire-authority']){const f=fixture(),r=f.settlement.receipt;
   if(change==='slot')r.transactions[0]!.slot=0;if(change==='clock')r.source.observedClockUnixTimestamp='0';if(change==='bank')r.source.observedAccountSlot=0;if(change==='term-context')r.source.originalTermContextSlot=r.source.observedAccountSlot+1;
   if(change==='source')r.source.trust='supplied-finalized-evidence';if(change==='finality')r.finalityAuthenticated=false;if(change==='clear')r.journalClearingAuthorized=true;if(change==='sign')r.signingAuthorized=true;if(change==='broadcast')r.broadcastAuthorized=true;if(change==='wire-authority')f.wires[0]!.relayAuthorized=true;
   expect(Schema.safeParse(f).success,change).toBe(false);
  }
 });
 it('rejects oversized arrays before child access and invalid amounts before BigInt',()=>{
  let touched=0;const huge=Array(10001);Object.defineProperty(huge,0,{get(){touched++;throw Error('must not traverse');}});
  const f=fixture();for(const x of [{...f,wires:huge},{...f,settlement:{...f.settlement,receipt:{...f.settlement.receipt,transactions:huge}}}])expect(Schema.safeParse(x).success).toBe(false);expect(touched).toBe(0);
  const spy=vi.spyOn(globalThis,'BigInt');try{for(const amount of ['x','01','-1','9'.repeat(100000)]){const x=fixture();x.settlement.receipt.paidKeepBaseUnits=amount;expect(Schema.safeParse(x).success).toBe(false);}expect(spy.mock.calls.some(([v])=>typeof v==='string'&&(!/^[0-9]+$/.test(v)||v.length>20))).toBe(false);}finally{spy.mockRestore();}
 });
 it('rejects malformed microsecond times, unknown fields and caller-selected submission authority',()=>{
  for(const time of ['2035-02-30T00:00:02.123456Z','2035-01-01T00:00:02.123Z','2035-01-01T00:00:02.1234567Z']){const f=fixture();f.settlement.settledAt=time;expect(Schema.safeParse(f).success).toBe(false);}
  const f=fixture();expect(Schema.safeParse({...f,privateSnapshot:{}}).success).toBe(false);expect(Schema.safeParse({...f,wires:[{...f.wires[0],extra:true}]}).success).toBe(false);
  const wire=Buffer.from(f.wires[0]!.signedTransactionHex,'hex').toString('base64'),request={idempotencyKey:f.idempotencyKey,signedTransaction:wire};expect(MiningTaxClaimSubmitRequestSchema.parse(request)).toEqual(request);
  for(const extra of [{wallet:f.wallet},{ordinal:0},{amount:'3'},{relayAuthorized:true}])expect(MiningTaxClaimSubmitRequestSchema.safeParse({...request,...extra}).success).toBe(false);
  for(const value of [wire+'=',wire+'\n','A'.repeat(1648),'AQ==',wire.slice(0,-2)+'B='])expect(MiningTaxClaimSubmitRequestSchema.safeParse({...request,signedTransaction:value}).success).toBe(false);
 });
 it('returns a deeply frozen owned tree and never turns a server receipt into journal-clear permission',()=>{
  const f=fixture(),out=validateMiningTaxClaimRecoveryEnvelope(f);f.wires[0]!.signature='changed';expect(out.wires[0]!.signature).not.toBe('changed');expect(Object.isFrozen(out.settlement!.receipt.transactions[0])).toBe(true);expect(out.settlement!.receipt.journalClearingAuthorized).toBe(false);
 });
});
